import { readFile } from 'node:fs/promises';
import path from 'node:path';

// Production HTML is generated by export-explore.mjs after the Next export.
// In development, serve that same archive through the normal app origin.
export const dynamic = 'force-static';
export function generateStaticParams() { return [{ path: [] }]; }

export async function GET(_request: Request, context: { params: Promise<{ path?: string[] }> }) {
  if (process.env.NODE_ENV === 'production') {
    return new Response('The exploration archive is generated during postbuild.', {
      headers: { 'Content-Type': 'text/html; charset=utf-8' },
    });
  }
  const segments = (await context.params).path ?? [];
  if (segments.some(segment => !/^[a-z0-9-]+$/.test(segment))) {
    return new Response('Not found', { status: 404 });
  }
  try {
    const html = await readFile(path.join(process.cwd(), 'out', 'explore', ...segments, 'index.html'));
    return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
    return new Response('This archive page is unavailable. Run npm run build -- --webpack to generate or refresh the exploration archive.', {
      status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}
